package io.knowledgebrain.content;
import java.util.*;import java.io.IOException;import jakarta.servlet.http.HttpServletRequest;import org.springframework.web.bind.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.MeterRegistry;import tools.jackson.databind.json.JsonMapper;
@RestController @ConditionalOnProperty(name="brain.content.api.enabled",havingValue="true") @RequestMapping("/api/spaces/{spaceId}/questions")
final class QuestionController {
 private final QuestionStore store;private final SpaceAuthorizationClient authority;private final MeterRegistry metrics;private final String origin;private final JsonMapper json=JsonMapper.builder().enable(tools.jackson.databind.DeserializationFeature.FAIL_ON_TRAILING_TOKENS).enable(tools.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).build();
 QuestionController(QuestionStore store,SpaceAuthorizationClient authority,MeterRegistry metrics,@Value("${brain.content.browser-origin}")String origin){this.store=store;this.authority=authority;this.metrics=metrics;this.origin=origin;}
 static String tag(long version){return "\"qu"+version+"\"";}
 static long version(HttpServletRequest r){var values=Collections.list(r.getHeaders("If-Match"));if(values.isEmpty())throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,"If-Match required");if(values.size()!=1||!values.getFirst().matches("\"qu[1-9][0-9]{0,18}\""))throw QuestionRules.bad();try{return Long.parseLong(values.getFirst().substring(3,values.getFirst().length()-1));}catch(NumberFormatException e){throw QuestionRules.bad();}}
 static String parent(HttpServletRequest r){var h=Collections.list(r.getHeaders("traceparent"));if(h.size()==1&&h.getFirst().matches("00-[0-9a-f]{32}-[0-9a-f]{16}-[0-9a-f]{2}")&&!h.getFirst().substring(3,35).equals("0".repeat(32))&&!h.getFirst().substring(36,52).equals("0".repeat(16)))return h.getFirst();return "00-"+UUID.randomUUID().toString().replace("-","")+"-"+UUID.randomUUID().toString().replace("-","").substring(0,16)+"-01";}
 static void parameters(HttpServletRequest r,Set<String> allowed){for(var p:r.getParameterMap().entrySet())if(!allowed.contains(p.getKey())||p.getValue().length!=1)throw QuestionRules.bad();if(Set.of("GET","DELETE").contains(r.getMethod())&&(r.getContentLengthLong()>0||r.getHeader("Transfer-Encoding")!=null))throw QuestionRules.bad();}
 static long number(String raw,long fallback,long max){if(raw==null)return fallback;if(!raw.matches("[1-9][0-9]{0,18}"))throw QuestionRules.bad();try{long v=Long.parseLong(raw);if(v>max)throw QuestionRules.bad();return v;}catch(NumberFormatException e){throw QuestionRules.bad();}}
 private UUID authorize(UUID space,HttpServletRequest r,boolean write,String trace){if(!r.isSecure())throw QuestionRules.bad();if(write&&(Collections.list(r.getHeaders("Origin")).size()!=1||!origin.equals(r.getHeader("Origin"))||r.getHeader("Sec-Fetch-Site")!=null&&!r.getHeader("Sec-Fetch-Site").equals("same-origin")))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Same-origin request required");String token=null;if(r.getCookies()!=null)for(var c:r.getCookies())if(c.getName().equals("__Host-brain_guest")){if(token!=null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Ambiguous session");token=c.getValue();}return authority.authorizeQuestion(space,token,write,trace);}
 private QuestionStore.Input body(HttpServletRequest r)throws IOException{if(!MediaType.APPLICATION_JSON_VALUE.equalsIgnoreCase(Optional.ofNullable(r.getContentType()).orElse("").split(";",2)[0].strip()))throw new ResponseStatusException(HttpStatus.UNSUPPORTED_MEDIA_TYPE,"JSON required");var bytes=r.getInputStream().readNBytes(262145);if(bytes.length>262144)throw new ResponseStatusException(HttpStatus.PAYLOAD_TOO_LARGE,"Question input too large");try{var v=json.readTree(bytes);if(v==null||!v.isObject()||v.size()!=4||!v.path("title").isString()||!v.path("context").isString()||!v.path("answer").isString()||!v.path("status").isString())throw QuestionRules.bad();var input=new QuestionStore.Input(v.path("title").asString(),v.path("context").asString(),v.path("answer").asString(),v.path("status").asString());QuestionRules.input(input);return input;}catch(RuntimeException e){throw QuestionRules.bad();}}
 private ResponseEntity<QuestionStore.Question> response(QuestionStore.Question value){return ResponseEntity.ok().eTag(tag(value.version())).cacheControl(CacheControl.noStore()).body(value);}
 @PostMapping ResponseEntity<QuestionStore.Question> create(@PathVariable String spaceId,HttpServletRequest r)throws IOException{parameters(r,Set.of());var space=QuestionRules.id(spaceId);String trace=parent(r);var actor=authorize(space,r,true,trace);var keys=Collections.list(r.getHeaders("Idempotency-Key"));if(keys.size()!=1||!keys.getFirst().matches("[0-9a-f]{32}"))throw QuestionRules.bad();var created=store.create(space,actor,keys.getFirst(),body(r),trace.substring(3,35));metrics.counter("brain.content.question.changes","type",created.replay()?"replayed":"created").increment();var v=created.question();return ResponseEntity.status(created.replay()?200:201).header("Location","/api/spaces/"+space+"/questions/"+v.questionId()).eTag(tag(v.version())).cacheControl(CacheControl.noStore()).body(v);}
 @GetMapping ResponseEntity<QuestionStore.Page> list(@PathVariable String spaceId,HttpServletRequest r){parameters(r,Set.of("state","status","after","limit"));var space=QuestionRules.id(spaceId);authorize(space,r,false,parent(r));metrics.counter("brain.content.question.reads","type","catalog").increment();return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(store.list(space,Optional.ofNullable(r.getParameter("state")).orElse("ACTIVE"),Optional.ofNullable(r.getParameter("status")).orElse("ALL"),r.getParameter("after"),(int)number(r.getParameter("limit"),20,100)));}
 @GetMapping("/{questionId}") ResponseEntity<QuestionStore.Question> get(@PathVariable String spaceId,@PathVariable String questionId,HttpServletRequest r){parameters(r,Set.of());var space=QuestionRules.id(spaceId);var id=QuestionRules.id(questionId);authorize(space,r,false,parent(r));metrics.counter("brain.content.question.reads","type","current").increment();return response(store.get(space,id));}
 @PutMapping("/{questionId}") ResponseEntity<QuestionStore.Question> update(@PathVariable String spaceId,@PathVariable String questionId,HttpServletRequest r)throws IOException{parameters(r,Set.of());var space=QuestionRules.id(spaceId);var id=QuestionRules.id(questionId);String trace=parent(r);var actor=authorize(space,r,true,trace);long expected=version(r);var value=store.change(space,id,actor,expected,body(r),false,trace.substring(3,35));metrics.counter("brain.content.question.changes","type","updated").increment();return response(value);}
 @DeleteMapping("/{questionId}") ResponseEntity<Void> retire(@PathVariable String spaceId,@PathVariable String questionId,HttpServletRequest r){parameters(r,Set.of());var space=QuestionRules.id(spaceId);var id=QuestionRules.id(questionId);String trace=parent(r);var actor=authorize(space,r,true,trace);var value=store.change(space,id,actor,version(r),null,true,trace.substring(3,35));metrics.counter("brain.content.question.changes","type","retired").increment();return ResponseEntity.noContent().eTag(tag(value.version())).cacheControl(CacheControl.noStore()).build();}
 @GetMapping("/{questionId}/revisions") ResponseEntity<List<QuestionStore.Revision>> history(@PathVariable String spaceId,@PathVariable String questionId,HttpServletRequest r){parameters(r,Set.of("before","limit"));var space=QuestionRules.id(spaceId);var id=QuestionRules.id(questionId);long before=number(r.getParameter("before"),Long.MAX_VALUE,Long.MAX_VALUE);int limit=(int)number(r.getParameter("limit"),5,10);authorize(space,r,false,parent(r));metrics.counter("brain.content.question.reads","type","history").increment();return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(store.history(space,id,before,limit));}
}
